app_css:
.tool-app-jobmargin { color: #14532d; max-width: 940px; margin-inline:auto; }
.tool-app-jobmargin .jm-h { margin: 18px 0 10px; font-size: 15px; font-weight: 700; }
.tool-app-jobmargin .jm-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
@media (max-width: 760px) { .tool-app-jobmargin .jm-grid { grid-template-columns: 1fr; } }
.tool-app-jobmargin .jm-panel { background: #f8fafc; border: 1px solid #bbf7d0; border-radius: 12px; padding: 14px; }
.tool-app-jobmargin .jm-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.tool-app-jobmargin .jm-field { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; margin-bottom: 10px; }
.tool-app-jobmargin input[type="text"], .tool-app-jobmargin input[type="number"] { border: 1px solid #86efac; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-jobmargin input:focus { outline: 2px solid #16a34a; outline-offset: 1px; }
.tool-app-jobmargin .jm-btn { background: #16A34A; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-jobmargin .jm-btn:hover { background: #15803d; }
.tool-app-jobmargin .jm-btn-ghost { background: transparent; color: #15803d; border: 1px solid #86efac; margin-top: 8px; }
.tool-app-jobmargin .jm-verdict { border-radius: 10px; padding: 12px 14px; font-size: 14px; font-weight: 600; background: #f0fdf4; border: 1px solid #bbf7d0; margin-bottom: 12px; }
.tool-app-jobmargin .jm-verdict.jm-good { background: #dcfce7; border-color: #4ade80; color: #166534; }
.tool-app-jobmargin .jm-verdict.jm-thin { background: #fffbeb; border-color: #fde68a; color: #92400e; }
.tool-app-jobmargin .jm-verdict.jm-bad { background: #fef2f2; border-color: #fecaca; color: #991b1b; }
.tool-app-jobmargin .jm-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
.tool-app-jobmargin .jm-stat { background: #fff; border: 1px solid #bbf7d0; border-radius: 10px; padding: 10px 14px; display: flex; flex-direction: column; gap: 2px; }
.tool-app-jobmargin .jm-stat span { font-size: 12px; font-weight: 600; color: #15803d; }
.tool-app-jobmargin .jm-stat strong { font-size: 22px; }
.tool-app-jobmargin .jm-stat.jm-highlight { background: #dcfce7; border-color: #4ade80; }
.tool-app-jobmargin .jm-note { font-size: 12px; color: #4d7c5f; margin: 10px 0 0; }
.tool-app-jobmargin .jm-saved { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-jobmargin .jm-saved li { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 8px; margin-bottom: 6px; font-size: 14px; background: #f0fdf4; border: 1px solid #bbf7d0; }
.tool-app-jobmargin .jm-saved li.jm-empty { justify-content: center; color: #4d7c5f; }
.tool-app-jobmargin .jm-del { background: transparent; border: 1px solid #fecaca; color: #b91c1c; border-radius: 8px; padding: 4px 10px; font-size: 12px; cursor: pointer; }
.tool-app-jobmargin .jm-tag { font-size: 12px; font-weight: 700; padding: 2px 10px; border-radius: 20px; white-space: nowrap; }
.tool-app-jobmargin .jm-tag.jm-good { background: #dcfce7; color: #166534; }
.tool-app-jobmargin .jm-tag.jm-thin { background: #fef3c7; color: #92400e; }
.tool-app-jobmargin .jm-tag.jm-bad { background: #fee2e2; color: #991b1b; }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat($(id).value); return isFinite(v) && v >= 0 ? v : 0; }
  function money(n) {
    if (!isFinite(n)) return '–';
    return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 2, minimumFractionDigits: 2 });
  }
  function pct(n) { return isFinite(n) ? n.toFixed(1) + '%' : '–'; }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var LS_KEY = 'toolapp-jobmargin-jobs';

  function calc() {
    var bid = num('jm-bid');
    var labor = num('jm-hours') * num('jm-rate');
    var materials = num('jm-materials');
    var subs = num('jm-subs');
    var direct = labor + materials + subs;
    var overheadPct = num('jm-overhead');
    var total = direct * (1 + overheadPct / 100);
    var target = num('jm-target');
    var profit = bid - total;
    var margin = bid > 0 ? (profit / bid) * 100 : NaN;
    var markup = total > 0 ? (profit / total) * 100 : NaN;
    var targetPrice = (target >= 100) ? NaN : total / (1 - target / 100);
    return {
      name: $('jm-name').value.trim(), bid: bid, total: total, profit: profit,
      margin: margin, markup: markup, targetPrice: targetPrice, target: target
    };
  }

  function classify(margin, target) {
    if (!isFinite(margin)) return 'thin';
    if (margin < 0) return 'bad';
    if (margin >= target && target > 0) return 'good';
    if (target > 0 && margin >= target * 0.7) return 'thin';
    return margin >= 15 ? 'good' : 'thin';
  }

  function render() {
    var r = calc();
    var cls = classify(r.margin, r.target);
    var verdict = $('jm-verdict');
    verdict.className = 'jm-verdict jm-' + cls;
    if (!isFinite(r.margin)) {
      verdict.textContent = 'Enter a bid price to see your margin.';
    } else if (cls === 'good') {
      verdict.textContent = 'Healthy margin: ' + pct(r.margin) + '. This job earns ' + money(r.profit) + '.';
    } else if (cls === 'thin') {
      verdict.textContent = 'Thin margin: ' + pct(r.margin) + '. You earn ' + money(r.profit) + ' — consider a higher bid.';
    } else {
      verdict.textContent = 'Losing money: ' + pct(r.margin) + '. This bid is below your cost of ' + money(r.total) + '.';
    }
    $('jm-totalCost').textContent = money(r.total);
    $('jm-profit').textContent = (isFinite(r.profit) && r.bid > 0) ? money(r.profit) : '–';
    $('jm-margin').textContent = pct(r.margin);
    $('jm-markup').textContent = pct(r.markup);
    $('jm-breakeven').textContent = money(r.total);
    $('jm-targetPrice').textContent = (isFinite(r.targetPrice) && r.target > 0 && r.target < 100) ? money(r.targetPrice) : '–';
  }

  function loadJobs() {
    try { var d = JSON.parse(localStorage.getItem(LS_KEY)); return Array.isArray(d) ? d : []; }
    catch (e) { return []; }
  }
  function saveJobs(jobs) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(jobs)); } catch (e) {}
  }

  function renderSaved() {
    var jobs = loadJobs();
    var list = $('jm-savedList');
    list.innerHTML = '';
    if (!jobs.length) {
      var li = document.createElement('li');
      li.className = 'jm-empty';
      li.textContent = 'No saved jobs yet. Jobs are stored in this browser only.';
      list.appendChild(li);
      return;
    }
    jobs.forEach(function (j, i) {
      var li = document.createElement('li');
      var cls = classify(j.margin, j.target);
      var label = cls === 'good' ? 'Healthy' : (cls === 'thin' ? 'Thin' : 'Losing');
      var left = document.createElement('div');
      var tag = document.createElement('span');
      tag.className = 'jm-tag jm-' + cls;
      tag.textContent = label;
      left.appendChild(document.createTextNode(esc(j.name || 'Unnamed job') + ' — bid ' + money(j.bid) + ', margin ' + pct(j.margin) + ' '));
      left.appendChild(tag);
      li.appendChild(left);
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'jm-del';
      del.textContent = 'Delete';
      del.setAttribute('data-i', String(i));
      del.addEventListener('click', function () {
        var cur = loadJobs();
        cur.splice(parseInt(del.getAttribute('data-i'), 10), 1);
        saveJobs(cur);
        renderSaved();
      });
      li.appendChild(del);
      list.appendChild(li);
    });
  }

  ['jm-bid', 'jm-hours', 'jm-rate', 'jm-materials', 'jm-subs', 'jm-overhead', 'jm-target']
    .forEach(function (id) { $(id).addEventListener('input', render); });
  $('jm-save').addEventListener('click', function () {
    var r = calc();
    if (r.bid <= 0) return;
    var jobs = loadJobs();
    jobs.unshift({ name: r.name, bid: r.bid, total: r.total, margin: r.margin, target: r.target });
    saveJobs(jobs.slice(0, 100));
    renderSaved();
  });
  $('jm-clear').addEventListener('click', function () {
    saveJobs([]);
    renderSaved();
  });

  renderSaved();
  render();
})();
